/**
 * Inline code, such as a token name, flag or path (`design/components/code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/code.module.css'

/** Inline code, such as a token name, flag or path: the inputs it takes, by the React member's prop names. */
export type CodeProps = Record<string, never>

/** Inline code, such as a token name, flag or path. */
@Component({
  selector: 'pm-code',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<code
[attr.class]="e1()"
data-member="code"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></code>`,
})
export class Code {
  protected readonly $ = useMember({ events: [], props: {} })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.code
  }
}
